<template>
  <div class="map-page">
    <header class="heading">
      <div><span>监测研判 · 空间入口</span><h1>边坡空间态势</h1><p>从空间位置发现风险，联动监测、雨情、巡查与预警处置。</p></div>
      <div class="heading-actions"><el-button @click="load">刷新态势</el-button><el-button @click="router.push('/spatial-data')">空间资料管理</el-button></div>
    </header>

    <section class="control-bar">
      <label><span>标段</span><el-select v-model="section" filterable @change="changeSection"><el-option v-for="item in sections" :key="item" :label="item" :value="item" /></el-select></label>
      <label><span>研判截止日期</span><el-date-picker v-model="asOf" type="date" value-format="YYYY-MM-DD" :clearable="false" @change="load" /></label>
      <label><span>风险状态</span><el-select v-model="filter" clearable placeholder="全部状态"><el-option label="监测预警" value="alarm" /><el-option label="巡查问题" value="attention" /><el-option label="数据滞后" value="stale" /><el-option label="正常监测" value="normal" /><el-option label="待完善坐标" value="missing" /></el-select></label>
      <label class="search-field"><span>快速定位</span><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="边坡名称或桩号" /></label>
      <div class="control-summary"><b>{{ rainSummary.recent_7d_mm.toFixed(1) }} mm</b><span>近7日累计雨量</span></div>
    </section>

    <section class="stats">
      <button v-for="item in stats" :key="item.key" :class="{active:filter===item.key}" type="button" @click="filter=item.key"><b>{{ item.value }}</b><span>{{ item.label }}</span></button>
    </section>

    <section class="workspace">
      <aside :class="{collapsed:listCollapsed}">
        <div class="aside-title"><div><b>边坡清单</b><small>{{ visible.length }} / {{ slopes.length }}</small></div><el-button link @click="listCollapsed=!listCollapsed">{{ listCollapsed?'展开':'收起' }}</el-button></div>
        <div v-if="!listCollapsed" class="slope-list">
          <button v-for="item in visible" :key="item.id" class="slope" :class="{chosen:selected?.id===item.id}" type="button" @click="choose(item)"><i :class="state(item)" /><span><b>{{ item.slope_name }}</b><small>{{ item.start_stake||'—' }} ～ {{ item.end_stake||'—' }}</small></span><em>{{ stateText(item) }}</em></button>
          <el-empty v-if="!visible.length" description="没有匹配的边坡" :image-size="70" />
        </div>
      </aside>

      <main class="map-box">
        <div ref="mapEl" class="map" />
        <div v-if="!mapReady" class="fallback"><el-icon><LocationFilled /></el-icon><b>{{ mapHint }}</b><span>配置高德 Web JS Key 后，可在此查看边坡空间态势。</span></div>
        <div class="map-tools">
          <b>业务图层</b>
          <el-checkbox v-model="layerVisibility.slopes" @change="draw">边坡状态</el-checkbox>
          <el-checkbox v-model="layerVisibility.points" @change="draw">监测点</el-checkbox>
          <el-checkbox v-model="layerVisibility.issues" @change="draw">巡查问题</el-checkbox>
          <el-checkbox v-model="layerVisibility.rain" @change="draw">雨量位置</el-checkbox>
          <el-checkbox v-model="layerVisibility.engineering" @change="draw">工程图层</el-checkbox>
          <el-divider />
          <el-radio-group v-model="baseMap" size="small" @change="changeBaseMap"><el-radio-button label="normal">标准</el-radio-button><el-radio-button label="satellite">卫星</el-radio-button></el-radio-group>
        </div>
        <div class="legend"><span><i class="alarm" />预警</span><span><i class="attention" />巡查问题</span><span><i class="stale" />数据滞后</span><span><i class="normal" />正常</span><span><i class="missing" />待定位</span></div>
        <div class="map-caption">{{ section }} · {{ asOf }} · {{ published.length }} 个已发布工程图层</div>
      </main>
    </section>

    <section class="time-strip">
      <div><b>近30日雨量时间轴</b><span>点击日期切换研判截面</span></div>
      <div class="rain-bars"><button v-for="item in rainfall" :key="item.rain_date" type="button" :class="{selected:item.rain_date===asOf}" :title="`${item.rain_date}：${item.amount_mm} mm`" @click="selectDate(item.rain_date)"><i :style="{height:rainHeight(item.amount_mm)}" /><small>{{ item.rain_date.slice(8) }}</small></button><span v-if="!rainfall.length">当前标段暂无近30日雨量记录</span></div>
    </section>

    <el-drawer v-model="detailVisible" title="边坡空间研判" size="560px">
      <div v-if="selected" class="detail-sheet">
        <div class="detail-heading"><div><span>{{ section }}</span><h2>{{ selected.slope_name }}</h2><p>{{ selected.start_stake||'未填起点' }} ～ {{ selected.end_stake||'未填终点' }}</p></div><el-tag :type="stateTag(selected)" effect="plain" size="large">{{ stateText(selected) }}</el-tag></div>
        <div class="risk-reason"><b>当前判断</b><p>{{ riskReason(selected) }}</p></div>
        <div class="metric-grid"><div><span>监测点</span><b>{{ selected.point_count }}</b><small>个</small></div><div><span>活动预警</span><b>{{ selected.active_alarm_count }}</b><small>条</small></div><div><span>未闭环巡查问题</span><b>{{ selected.open_inspection_count }}</b><small>项</small></div><div><span>近7日雨量</span><b>{{ rainSummary.recent_7d_mm.toFixed(1) }}</b><small>mm</small></div></div>
        <el-descriptions :column="1" border><el-descriptions-item label="最新监测">{{ date(selected.latest_monitor_date) }}</el-descriptions-item><el-descriptions-item label="最近巡查">{{ date(selected.latest_inspection_date) }}</el-descriptions-item><el-descriptions-item label="下次计划巡查">{{ date(selected.next_inspection_date) }}</el-descriptions-item><el-descriptions-item label="空间位置">{{ selected.longitude?`${selected.longitude}, ${selected.latitude}（${selected.coordinate_system||'未标注坐标系'}）`:'尚未维护坐标' }}</el-descriptions-item></el-descriptions>
        <section class="point-section"><div><b>已定位监测点</b><span>{{ selectedPoints.length }} 个</span></div><div v-if="selectedPoints.length" class="point-list"><button v-for="point in selectedPoints" :key="point.id" type="button" @click="goData(point)"><span><b>{{ point.point_name }}</b><small>{{ point.point_type }}</small></span><em>{{ date(point.latest_monitor_date) }}</em></button></div><el-empty v-else description="该边坡暂无已定位监测点" :image-size="62" /></section>
        <section v-if="selectedIssues.length" class="issue-section"><div><b>未闭环巡查问题</b><span>{{ selectedIssues.length }} 项</span></div><button v-for="issue in selectedIssues" :key="issue.id" type="button" @click="goInspection(issue)"><el-tag :type="issue.problem_level==='general'?'warning':'danger'" effect="plain">{{ problemLevel(issue.problem_level) }}</el-tag><span><b>{{ issue.problem_location||'未注明部位' }}</b><small>{{ issue.problems }}</small></span><em>查看</em></button></section>
        <div class="quick-actions"><el-button type="primary" @click="goData()">查看监测数据</el-button><el-button @click="goInspection()">巡查台账</el-button><el-button @click="goAlarm">异常报警</el-button><el-button @click="goSlope">边坡与测点</el-button></div>
      </div>
    </el-drawer>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { LocationFilled, Search } from '@element-plus/icons-vue'
import { dataRequest } from '../utils/request'

const router=useRouter(),mapEl=ref(),mapReady=ref(false),mapHint=ref('尚未配置高德地图密钥'),sections=ref([]),section=ref(''),asOf=ref(new Date().toISOString().slice(0,10)),slopes=ref([]),points=ref([]),issues=ref([]),layers=ref([]),rainfall=ref([]),weatherStation=ref(null),keyword=ref(''),filter=ref(''),selected=ref(null),detailVisible=ref(false),listCollapsed=ref(false),baseMap=ref('normal')
const rainSummary=reactive({recent_7d_mm:0,latest_mm:0}),layerVisibility=reactive({slopes:true,points:true,issues:true,rain:true,engineering:true})
let map,overlays=[],satelliteLayer,roadLayer
const published=computed(()=>layers.value.filter(item=>item.status==='published'))
function state(item){if(!item.longitude||!item.latitude)return'missing';if(Number(item.risk_rank)>=2)return'alarm';if(Number(item.open_inspection_count)>0)return'attention';if(!item.latest_monitor_date||daysSince(item.latest_monitor_date)>30)return'stale';return'normal'}
const stateText=item=>({alarm:'监测预警',attention:'巡查问题',stale:'数据滞后',normal:'正常监测',missing:'待完善坐标'})[state(item)]
const stateTag=item=>({alarm:'danger',attention:'warning',stale:'info',normal:'success',missing:'info'})[state(item)]
const visible=computed(()=>slopes.value.filter(item=>`${item.slope_name||''} ${item.start_stake||''} ${item.end_stake||''}`.toLowerCase().includes(keyword.value.toLowerCase())&&(!filter.value||state(item)===filter.value)))
const stats=computed(()=>[{key:'',label:'纳入地图边坡',value:slopes.value.length},{key:'alarm',label:'监测预警',value:slopes.value.filter(item=>state(item)==='alarm').length},{key:'attention',label:'巡查问题',value:slopes.value.filter(item=>state(item)==='attention').length},{key:'stale',label:'数据滞后',value:slopes.value.filter(item=>state(item)==='stale').length},{key:'missing',label:'待完善坐标',value:slopes.value.filter(item=>state(item)==='missing').length}])
const selectedPoints=computed(()=>points.value.filter(item=>Number(item.slope_id)===Number(selected.value?.id)&&item.longitude)),selectedIssues=computed(()=>issues.value.filter(item=>Number(item.slope_id)===Number(selected.value?.id)))
const daysSince=value=>Math.max(0,(new Date(`${asOf.value}T23:59:59`)-new Date(value))/86400000)
const date=value=>value?String(value).slice(0,10):'暂无数据'
const problemLevel=value=>({general:'一般',important:'重要',urgent:'紧急'})[value]||'未分级'
function riskReason(item){if(state(item)==='alarm')return`存在 ${item.active_alarm_count} 条未关闭监测预警，应优先核查监测曲线和现场情况。`;if(state(item)==='attention')return`存在 ${item.open_inspection_count} 项未闭环巡查问题，应跟进整改和复核。`;if(state(item)==='stale')return`最新监测距研判日期超过30天或尚无有效数据，应核查监测计划。`;if(state(item)==='missing')return'尚未维护边坡空间坐标，无法在地图中定位。';return'当前无活动预警和未闭环巡查问题，监测数据更新正常。'}

async function load(){try{const query=new URLSearchParams({...(section.value?{section:section.value}:{}),as_of:asOf.value});const response=await dataRequest(`/api/map-overview/overview?${query}`);const data=response.data||{};sections.value=data.sections||[];section.value=data.section||section.value;slopes.value=data.slopes||[];points.value=data.points||[];issues.value=data.issues||[];layers.value=data.layers||[];rainfall.value=data.rainfall||[];weatherStation.value=data.weather_station||null;Object.assign(rainSummary,data.rain_summary||{});if(selected.value){selected.value=slopes.value.find(item=>Number(item.id)===Number(selected.value.id))||null}await nextTick();draw()}catch(error){ElMessage.error(error.message)}}
async function changeSection(){selected.value=null;detailVisible.value=false;await load();fitMap()}
function selectDate(value){asOf.value=value;load()}
function choose(item){selected.value=item;detailVisible.value=true;if(map&&item.longitude)map.setZoomAndCenter(15,[Number(item.longitude),Number(item.latitude)])}
function goData(point){router.push({path:'/data-view',query:{section:section.value,slope_id:selected.value.id,...(point?{point_id:point.id}:{})}})}
function goInspection(issue){router.push({path:'/inspection-management',query:{...(issue?{inspection_id:issue.id}:{slope_id:selected.value.id}),section:section.value}})}
function goAlarm(){router.push({path:'/alarm-management',query:{slope_id:selected.value.id,section:section.value}})}
function goSlope(){router.push({path:'/slope-management',query:{slope_id:selected.value.id}})}

function addFeature(feature){const geometry=feature.geometry,properties=feature.properties||{};if(!geometry)return;let overlay;if(geometry.type==='Point')overlay=new window.AMap.Marker({position:geometry.coordinates,title:properties.name});if(geometry.type==='LineString')overlay=new window.AMap.Polyline({path:geometry.coordinates,strokeColor:'#237c87',strokeWeight:4});if(geometry.type==='Polygon')overlay=new window.AMap.Polygon({path:geometry.coordinates[0],strokeColor:'#157766',fillColor:'#37a88c',fillOpacity:.18});if(overlay){map.add(overlay);overlays.push(overlay)}}
function markerContent(className,label=''){return `<span class="map-marker ${className}">${label?`<em>${label}</em>`:''}</span>`}
function draw(){if(!map||!window.AMap)return;if(overlays.length)map.remove(overlays);overlays=[];if(layerVisibility.engineering)published.value.forEach(layer=>(layer.geometry?.features||[]).forEach(addFeature));if(layerVisibility.slopes)visible.value.forEach(item=>{if(!item.longitude)return;const marker=new window.AMap.Marker({position:[Number(item.longitude),Number(item.latitude)],title:item.slope_name,content:markerContent(state(item)),offset:new window.AMap.Pixel(-10,-10),zIndex:120});marker.on('click',()=>choose(item));map.add(marker);overlays.push(marker)});if(layerVisibility.points)points.value.filter(item=>item.longitude).forEach(item=>{const marker=new window.AMap.Marker({position:[Number(item.longitude),Number(item.latitude)],title:item.point_name,content:markerContent('point'),offset:new window.AMap.Pixel(-6,-6),zIndex:130});marker.on('click',()=>{const slope=slopes.value.find(value=>Number(value.id)===Number(item.slope_id));if(slope)choose(slope)});map.add(marker);overlays.push(marker)});if(layerVisibility.issues)issues.value.filter(item=>item.longitude).forEach(item=>{const marker=new window.AMap.Marker({position:[Number(item.longitude),Number(item.latitude)],title:item.problems,content:markerContent('issue','!'),offset:new window.AMap.Pixel(-9,-9),zIndex:140});marker.on('click',()=>{const slope=slopes.value.find(value=>Number(value.id)===Number(item.slope_id));if(slope)choose(slope)});map.add(marker);overlays.push(marker)});if(layerVisibility.rain&&weatherStation.value?.longitude){const marker=new window.AMap.Marker({position:[Number(weatherStation.value.longitude),Number(weatherStation.value.latitude)],title:weatherStation.value.location_name||'雨量位置',content:markerContent('rain',`${rainSummary.recent_7d_mm}mm`),offset:new window.AMap.Pixel(-18,-18),zIndex:110});map.add(marker);overlays.push(marker)}}
function initMap(){const key=import.meta.env.VITE_AMAP_KEY;if(!key)return;const securityCode=import.meta.env.VITE_AMAP_SECURITY_JS_CODE;if(securityCode)window._AMapSecurityConfig={securityJsCode:securityCode};if(window.AMap)return makeMap();const script=document.createElement('script');script.src=`https://webapi.amap.com/maps?v=2.0&key=${key}`;script.onload=makeMap;script.onerror=()=>mapHint.value='地图加载失败，请检查密钥、域名白名单和网络';document.head.appendChild(script)}
function makeMap(){map=new window.AMap.Map(mapEl.value,{zoom:7,center:[108.9,34.25],mapStyle:'amap://styles/whitesmoke'});satelliteLayer=new window.AMap.TileLayer.Satellite();roadLayer=new window.AMap.TileLayer.RoadNet();mapReady.value=true;draw();fitMap()}
function fitMap(){if(!map)return;const positioned=slopes.value.filter(item=>item.longitude);if(positioned.length===1)map.setZoomAndCenter(14,[Number(positioned[0].longitude),Number(positioned[0].latitude)]);else if(positioned.length)map.setFitView(overlays.filter(item=>item instanceof window.AMap.Marker),false,[80,80,80,80],11)}
function changeBaseMap(value){if(!map)return;if(value==='satellite'){map.add([satelliteLayer,roadLayer])}else{map.remove([satelliteLayer,roadLayer])}}
function rainHeight(value){const max=Math.max(1,...rainfall.value.map(item=>Number(item.amount_mm||0)));return `${Math.max(3,Math.round(Number(value||0)/max*34))}px`}
watch([keyword,filter],draw)
onMounted(async()=>{await load();await nextTick();initMap()})
onBeforeUnmount(()=>map?.destroy?.())
</script>

<style scoped>
.map-page{--ink:#1e3741;--muted:#71848b;--line:#d7e3e4;--teal:#147766;min-height:calc(100vh - 52px);padding:18px 22px 38px;background:#f3f7f6;color:var(--ink)}.heading,.control-bar,.stats,.workspace,.time-strip{max-width:1580px;margin-right:auto;margin-left:auto}.heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:13px}.heading span{color:var(--teal);font-size:12px;font-weight:750}.heading h1{margin:3px 0;font-size:28px}.heading p{margin:0;color:var(--muted);font-size:13px}.heading-actions{display:flex;gap:8px}.control-bar{display:grid;grid-template-columns:190px 190px 180px minmax(220px,1fr) auto;gap:12px;align-items:end;padding:12px 15px;border:1px solid var(--line);background:#fff}.control-bar label{display:flex;min-width:0;flex-direction:column;gap:5px}.control-bar label>span{color:#61747c;font-size:12px;font-weight:600}.control-bar :deep(.el-select),.control-bar :deep(.el-date-editor){width:100%}.control-summary{display:flex;min-width:138px;flex-direction:column;padding:0 8px;border-left:1px solid var(--line)}.control-summary b{font-size:18px;color:var(--teal)}.control-summary span{color:var(--muted);font-size:11px}.stats{display:grid;grid-template-columns:repeat(5,1fr);margin-top:10px;border:1px solid var(--line);background:#fff}.stats button{display:flex;align-items:baseline;gap:9px;padding:10px 16px;border:0;border-right:1px solid var(--line);background:#fff;text-align:left;cursor:pointer}.stats button:last-child{border:0}.stats button.active{background:#eaf6f2}.stats b{font-size:22px}.stats span{color:var(--muted);font-size:12px}.workspace{display:grid;grid-template-columns:auto minmax(500px,1fr);height:620px;margin-top:10px;border:1px solid var(--line);background:#fff}.workspace>aside{width:280px;padding:14px;border-right:1px solid var(--line);transition:width .2s}.workspace>aside.collapsed{width:72px}.aside-title{display:flex;align-items:center;justify-content:space-between}.aside-title>div{display:flex;flex-direction:column}.